import{_ as l,a0 as p,w as r,s as c,ao as o,I as t,x as e,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"screen 命令使用及示例 | LCTT x X-CMD","titleTemplate":false,"description":"screen 命令使用及示例 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"screen 命令使用及示例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"screen 命令使用及示例 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170210 Basic screen command usage and examples","title":"screen 命令使用及示例","tag":"201702","desc":""},"relativePath":"201702/20170210 Basic screen command usage and examples.md","filePath":"[post].md"}'),d={name:"201702/20170210 Basic screen command usage and examples.md"};function h(g,s,k,b,u,m){const a=p("Link");return r(),c("div",null,[s[13]||(s[13]=o(`<h1 id="screen-命令使用及示例" tabindex="-1">screen 命令使用及示例 <a class="header-anchor" href="#screen-命令使用及示例" aria-label="Permalink to “screen 命令使用及示例”">​</a></h1><p><img src="https://www.rosehosting.com/blog/wp-content/uploads/2017/02/linux-screen-usage-examples.jpg" alt="linux screen command usage and examples"></p><p><code>screen</code> 是一个非常有用的命令，提供从单个 SSH 会话中使用多个 shell 窗口（会话）的能力。当会话被分离或网络中断时，screen 会话中启动的进程仍将运行，你可以随时重新连接到 screen 会话。如果你想运行一个持久的进程或者从多个位置连接到 shell 会话，这也很方便。</p><p>在本文中，我们将展示在 Linux 上安装和使用 <code>screen</code> 的基本知识。</p><h3 id="如何安装-screen" tabindex="-1">如何安装 screen <a class="header-anchor" href="#如何安装-screen" aria-label="Permalink to “如何安装 screen”">​</a></h3><p><code>screen</code> 在一些流行的发行版上已经预安装了。你可以使用下面的命令检查是否已经在你的服务器上安装了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>screen -v</span></span>
<span class="line"><span>Screen version 4.00.03 (FAU)</span></span></code></pre></div><p>如果在 Linux 中还没有 <code>screen</code>，你可以使用系统提供的包管理器很简单地安装它。</p><p><strong>CentOS/RedHat/Fedora</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>yum -y install screen</span></span></code></pre></div><p><strong>Ubuntu/Debian</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt-get -y install screen</span></span></code></pre></div><h3 id="如何启动一个-screen-会话" tabindex="-1">如何启动一个 screen 会话 <a class="header-anchor" href="#如何启动一个-screen-会话" aria-label="Permalink to “如何启动一个 screen 会话”">​</a></h3><p>你可以在命令行中输入 <code>screen</code> 来启动它，接着会有一个看上去和命令行提示符一样的 <code>screen</code> 会话启动。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>screen</span></span></code></pre></div><p>使用描述性名称启动屏幕会话是一个很好的做法，这样你可以轻松地记住会话中正在运行的进程。要使用会话名称创建新会话，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>screen -S name</span></span></code></pre></div><p>将 “name” 替换为对你会话有意义的名字。</p><h3 id="从-screen-会话中分离" tabindex="-1">从 screen 会话中分离 <a class="header-anchor" href="#从-screen-会话中分离" aria-label="Permalink to “从 screen 会话中分离”">​</a></h3><p>要从当前的 screen 会话中分离，你可以按下 <code>Ctrl-A</code> 和 <code>d</code>。所有的 screen 会话仍将是活跃的，你之后可以随时重新连接。</p><h3 id="重新连接到-screen-会话" tabindex="-1">重新连接到 screen 会话 <a class="header-anchor" href="#重新连接到-screen-会话" aria-label="Permalink to “重新连接到 screen 会话”">​</a></h3><p>如果你从一个会话分离，或者由于某些原因你的连接被中断了，你可以使用下面的命令重新连接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>screen -r</span></span></code></pre></div><p>如果你有多个 screen 会话，你可以用 <code>ls</code> 参数列出它们。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>screen -ls</span></span>
<span class="line"><span></span></span>
<span class="line"><span>There are screens on:</span></span>
<span class="line"><span>7880.session    (Detached)</span></span>
<span class="line"><span>7934.session2   (Detached)</span></span>
<span class="line"><span>7907.session1   (Detached)</span></span>
<span class="line"><span>3 Sockets in /var/run/screen/S-root.</span></span></code></pre></div><p>在我们的例子中，我们有三个活跃的 screen 会话。因此，如果你想要还原 “session2” 会话，你可以执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>screen -r 7934</span></span></code></pre></div><p>或者使用 screen 名称。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>screen -r -S session2</span></span></code></pre></div><h3 id="中止-screen-会话" tabindex="-1">中止 screen 会话 <a class="header-anchor" href="#中止-screen-会话" aria-label="Permalink to “中止 screen 会话”">​</a></h3><p>有几种方法来中止 screen 会话。你可以按下 <code>Ctrl+d</code>，或者在命令行中使用 <code>exit</code> 命令。</p><p>要查看 <code>screen</code> 命令所有有用的功能，你可以查看 <code>screen</code> 的 man 手册。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man screen</span></span>
<span class="line"><span></span></span>
<span class="line"><span>NAME</span></span>
<span class="line"><span>screen - screen manager with VT100/ANSI terminal emulation</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SYNOPSIS</span></span>
<span class="line"><span>screen [ -options ] [ cmd [ args ] ]</span></span>
<span class="line"><span>screen -r [[pid.]tty[.host]]</span></span>
<span class="line"><span>screen -r sessionowner/[[pid.]tty[.host]]</span></span></code></pre></div><hr><p>顺便说一下，如果你喜欢这篇文章，请在社交网络上与你的朋友分享，或者在评论区留下评论。谢谢。</p><hr>`,36)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),n(a,{href:"https://www.rosehosting.com/blog/basic-screen-command-usage-and-examples/"},{default:i(()=>[...s[0]||(s[0]=[e("https://www.rosehosting.com/blog/basic-screen-command-usage-and-examples/",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=e("作者：",-1)),n(a,{href:"https://www.rosehosting.com/blog/basic-screen-command-usage-and-examples/"},{default:i(()=>[...s[2]||(s[2]=[e("rosehosting.com",-1)])]),_:1}),s[6]||(s[6]=e(" 译者：",-1)),n(a,{href:"https://github.com/geekpi"},{default:i(()=>[...s[3]||(s[3]=[e("geekpi",-1)])]),_:1}),s[7]||(s[7]=e(" 校对：",-1)),n(a,{href:"https://github.com/jasminepeng"},{default:i(()=>[...s[4]||(s[4]=[e("jasminepeng",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[8]||(s[8]=[e("LCTT",-1)])]),_:1}),s[11]||(s[11]=e(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:i(()=>[...s[9]||(s[9]=[e("Linux中国",-1)])]),_:1}),s[12]||(s[12]=e(" 荣誉推出",-1))])])}const y=l(d,[["render",h]]);export{C as __pageData,y as default};
